// ── GATE: Roster auth + Redis rate limit (zero-trust) ───────────────────────
const crypto = require('crypto');

const RATE_LIMIT_WINDOW_SEC = 60;
const RATE_LIMIT_MAX = 100;

function timingSafeEqualStrings(a, b) {
  const sa = String(a ?? '');
  const sb = String(b ?? '');
  const ba = Buffer.from(sa, 'utf8');
  const bb = Buffer.from(sb, 'utf8');
  if (ba.length !== bb.length) return false;
  return crypto.timingSafeEqual(ba, bb);
}

function readAgencyAuthHeader(h) {
  const bag = h ?? {};
  for (const [key, value] of Object.entries(bag)) {
    if (key && key.toLowerCase() === 'x-agency-auth') {
      const v = String(value ?? '').trim();
      if (v) return v;
    }
  }
  return '';
}

function redisBase() {
  const base = String($vars['REDIS_CONNECTION_URL'] ?? $env['REDIS_CONNECTION_URL'] ?? '').replace(/\/+$/, '');
  if (!base) {
    console.error('CRITICAL: REDIS_CONNECTION_URL missing from environment');
    return '';
  }
  return base;
}

async function redisHeaders() {
  const token = String($vars['REDIS_REST_TOKEN'] ?? $env['REDIS_REST_TOKEN'] ?? '').trim();
  const h = {};
  if (token) h.Authorization = `Bearer ${token}`;
  return h;
}

async function redisIncrFail(key, windowSec) {
  const base = redisBase();
  if (!base) throw new Error('REDIS_UNAVAILABLE');
  const h = await redisHeaders();
  const enc = encodeURIComponent(key);
  const incrRes = await fetch(`${base}/incr/${enc}`, { method: 'POST', headers: h });
  if (!incrRes.ok) throw new Error(`REDIS_HTTP_FAIL: incr ${incrRes.status}`);
  const incrData = await incrRes.json();
  const count = Number(incrData.result ?? 0);
  if (count === 1) {
    await fetch(`${base}/expire/${enc}/${windowSec}`, { method: 'POST', headers: h });
  }
  return count;
}

async function redisIncrWindow(key, windowSec, max) {
  const count = await redisIncrFail(key, windowSec);
  if (count > max) {
    throw new Error(`RATE_LIMIT: ${count} requests in ${windowSec}s window (max ${max})`);
  }
  return count;
}

return (async () => {
  const rawItem = $input.first().json ?? {};
  const headers = rawItem.headers ?? {};
  const incoming = readAgencyAuthHeader(headers);
  const expected = String($vars['N8N_AUTH_KEY'] ?? $env['N8N_AUTH_KEY'] ?? $vars['DASHBOARD_AUTH_KEY'] ?? $env['DASHBOARD_AUTH_KEY'] ?? '').trim();

  // Step 1 — Auth first (fail fast before rate-limit Redis work)
  if (!expected) {
    throw new Error('AUTH_FAIL: N8N_AUTH_KEY is not configured');
  }

  if (!incoming || !timingSafeEqualStrings(incoming, expected)) {
    throw new Error('AUTH_FAIL: Invalid or missing x-agency-auth header');
  }

  // Step 2–4 — Redis throttle after successful auth
  const fwd = headers['x-forwarded-for'] ?? headers['X-Forwarded-For'] ?? '';
  const clientIp = String(fwd).split(',')[0].trim() || 'unknown';
  const clinicId = String($vars['CLINIC_ID'] ?? 'temara').trim();
  const rateKeyId = crypto.createHash('sha256').update(incoming, 'utf8').digest('hex').slice(0, 16);
  const rateLimitKey = `ratelimit:roster:${clinicId}:${rateKeyId}:${clientIp}`;

  try {
    await redisIncrWindow(rateLimitKey, RATE_LIMIT_WINDOW_SEC, RATE_LIMIT_MAX);
  } catch (error) {
    const msg = String(error?.message ?? error);
    if (msg.startsWith('RATE_LIMIT')) {
      throw new Error(msg);
    }
    console.error('Redis unreachable during roster rate limit, failing open:', msg);
  }

  return $input.all();
})();

const errMsg = ($input.first()?.json?.message ?? 'Unauthorized').toString();
const isAuth = errMsg.startsWith('AUTH_FAIL');
const isRate = errMsg.startsWith('RATE_LIMIT');
return [{
  json: {
    httpStatus: isAuth ? 401 : isRate ? 429 : 503,
    body: {
      ok: false,
      error: isAuth ? 'Unauthorized' : isRate ? 'Too Many Requests' : 'Service Unavailable',
      message: isAuth
        ? 'Invalid or missing credentials'
        : isRate
          ? 'Rate limit exceeded. Retry shortly.'
          : 'Service temporarily unavailable',
    },
  },
}];

// Return the full Feuille 1 grid as a JSON array for the assistant dashboard.
// Column headers must match the clinic sheet schema:
//   Patient (Nom Complet), Date & Heure du RDV, Statut du RDV,
//   Cal Booking ID, Téléphone (WhatsApp), Email Contact, Motif de Consultation, etc.

const rows = $input.all().map(item => item.json ?? {});

return [{ json: rows }];
